PRAGMA defer_foreign_keys = ON;
UPDATE exams SET series_id = NULL WHERE series_id IS NOT NULL;
UPDATE catalog SET class_id = NULL, session_id = NULL WHERE class_id IS NOT NULL OR session_id IS NOT NULL;
DELETE FROM catalog WHERE kind IN ('class', 'session', 'series');
CREATE TABLE catalog_new (id TEXT PRIMARY KEY, center_id TEXT NOT NULL REFERENCES centers(id), kind TEXT NOT NULL CHECK(kind IN ('subject','group')), name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, UNIQUE(center_id,id));
INSERT INTO catalog_new (id, center_id, kind, name, active, version) SELECT id, center_id, kind, name, active, version FROM catalog WHERE kind IN ('subject','group');
DROP TABLE catalog;
ALTER TABLE catalog_new RENAME TO catalog;
CREATE INDEX catalog_list ON catalog(center_id,kind,active,name,id);
CREATE TRIGGER catalog_revision_update AFTER UPDATE ON catalog BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER group_count_insert AFTER INSERT ON catalog WHEN NEW.kind='group' BEGIN UPDATE centers SET groups_count=groups_count+NEW.active WHERE id=NEW.center_id; END;
CREATE TRIGGER group_count_update AFTER UPDATE OF active ON catalog WHEN OLD.kind='group' AND OLD.active!=NEW.active BEGIN UPDATE centers SET groups_count=groups_count+NEW.active-OLD.active WHERE id=NEW.center_id; END;
CREATE TABLE exams_new (id TEXT PRIMARY KEY, center_id TEXT NOT NULL REFERENCES centers(id), name TEXT NOT NULL, exam_date TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, UNIQUE(center_id,id));
INSERT INTO exams_new (id, center_id, name, exam_date, active, version) SELECT id, center_id, name, exam_date, active, version FROM exams;
DROP TABLE exams;
ALTER TABLE exams_new RENAME TO exams;
CREATE INDEX exams_list ON exams(center_id,active,exam_date,id);
CREATE INDEX exams_name ON exams(center_id,active,name,id);
CREATE TRIGGER exam_revision_update AFTER UPDATE ON exams BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER exam_count_insert AFTER INSERT ON exams BEGIN UPDATE centers SET exams_count=exams_count+NEW.active WHERE id=NEW.center_id; END;
CREATE TRIGGER exam_count_update AFTER UPDATE OF active ON exams WHEN OLD.active!=NEW.active BEGIN UPDATE centers SET exams_count=exams_count+NEW.active-OLD.active WHERE id=NEW.center_id; END;
PRAGMA defer_foreign_keys = OFF;
